DECKBLATT = {
    'hintergrund': 'Der Entwurf eines Gesetzes über eine nationale Kunststoffverpackungsteuer (KunststoffVStG) sieht einen Steuersatz von 550 €/t vor, der auf bestimmte industrielle Vorprodukte und Verpackungsmaterialien erhoben werden soll. Die Abgrenzung der steuerpflichtigen Erzeugnisse erfolgt anhand ausgewählter Zolltarifnummern der Kombinierten Nomenklatur (KN), die auch dem Warenverzeichnis für die Außenhandelsstatistik (WA) zugrunde liegt. Damit wird eine für den grenzüberschreitenden Warenverkehr verwendete Klassifikation zugleich zur Grundlage der Besteuerung inländisch hergestellter Erzeugnisse.\nDie zentrale methodische Schwierigkeit besteht darin, dass Außenhandel und Inlandsproduktion nach unterschiedlichen Gütersystematiken erfasst werden. Um den anhand von Zolltarifnummern definierten Warenkreis in der Produktionsstatistik abzubilden, müssen WA-Nummern mit Produktionsmeldenummern (GP) verknüpft werden.',
    'gemeinsam': 'Die gemeinsame Betrachtung von Außenhandelscodes und Produktionscodes ist für Unternehmen wichtig, weil Außenhandelsmeldungen auf KN-/WA-Nummern beruhen, Produktionsmeldungen dagegen auf GP-Nummern. Beide Meldungen müssen denselben Artikel nachvollziehbar, aber nicht zwingend mit deckungsgleichen Warengruppen abbilden. Die Übersicht hilft, solche Unterschiede zu erkennen, die steuerliche Einordnung konsistent zu dokumentieren und vermeidbare Widersprüche zwischen Produktionsmeldung, Außenhandelsmeldung und späterer Steueranmeldung zu verhindern. Eine statistische Zuordnung ersetzt dabei nicht die Prüfung der konkreten Produkteigenschaften.',
    'wa_bekannt': 'Die Ansicht enthält vollständig alle achtstelligen WA2026-Nummern der Positionen 3915 bis 3926 ("Kunststoffe und Waren daraus") sowie die übrigen Codes der untersuchten gesetzlichen Auswahl. Innerhalb dieses Kunststoffwarenbereichs ist damit auch die Untergliederung der nicht ausgewählten Codes vollständig. Außerhalb davon ist der Vergleichsbestand nicht abschließend. Die Gemeinsamkeit beruht auf Produktgruppen wie Folien, Platten, Profile, Schläuche und Kunststoffwaren; nicht jede Warenart ist funktional eine Alternative zu Verpackungen.\n\nHinweis: Für verbindliche Zolltarifauskünfte (vZTA) ist die Zollverwaltung Ansprechpartner. Die Zolltarifnummern sind bis zum 8-Steller identisch mit den Warennummern für die Außenhandelsstatistik. Nur bei der Einfuhr aus Drittländern können bis zu drei Stellen hinzukommen (elfstellige Zolltarifnummer).',
    'gp_bekannt': 'Die Ansicht enthält alle 130 neunstelligen GP2026-Nummern unter 2221, 2222, 2223 und 2226. Gesetzlich erfasste und ausgewählte und nicht erfasste WA-Verknüpfungen stehen nebeneinander.',
    'dokumentation': 'In den Tabellenblättern „Außenhandelscode bekannt“ und „Produktionscode bekannt“ steht rechts die Spalte „Dokumentieren“. Über das Dropdown lässt sich je Datenzeile ein Häkchen (✓) setzen. Alle markierten Zeilen erscheinen automatisch im  Blatt „Dokumentation“, einschließlich Quellblatt, Code, amtlicher Bezeichnung und der zugehörigen Angaben. Mit ☐ wird die Auswahl wieder aufgehoben. Die Häkchen dienen der eigenen Nachvollziehbarkeit und stellen keine Aussage über eine tatsächliche Steuerpflicht dar. Die Dokumentation ist eine laufende Auswahl, kein unveränderliches Archiv; ein fester Stand erfordert eine datierte Dateikopie oder einen separaten Export.',
    'lesart': 'Beide Ansichten sind nach amtlichen WA-Positionen beziehungsweise GP-Güterklassen gegliedert. Die Filter gelten jeweils innerhalb eines Abschnitts. „andere“ steht nur im Zusammenhang mit der übergeordneten amtlichen Warenbeschreibung. Gesetzliche Zusatzmerkmale und redaktionelle Einordnung sind separat ausgewiesen. Die Hinweise beschreiben den Datenbestand, ohne einen Prüfauftrag zu formulieren.',
    'stand': 'Arbeitsfassung 10.11.2026; WA2026/GP2026; Grundlage ist der bislang untersuchte Entwurfswortlaut, keine bestätigte aktuelle oder geltende Gesetzesfassung. „Code ausgewählt“ beschreibt den Warenkreis, nicht sämtliche Voraussetzungen tatsächlicher Steuerpflicht.',
}

QUELLEN = [
    ('Rechtsstand', 'Arbeitsfassung 10.11.2026 zum bislang untersuchten Entwurfswortlaut, § 1 Abs. 2 Nr. 1–4 KunststoffVStG. Keine Bestätigung einer aktuellen konsolidierten oder geltenden Gesetzesfassung.'),
    ('WA-Erweiterung', 'Alle achtstelligen WA2026-Nummern unter 3915,3916,3917,3918,3919,3920,3921,3922,3923,3924,3925,3926 sind enthalten. Die Vollständigkeit wurde gegen „Jahr 2026“ der gelieferten warensystematischen Gegenüberstellung abgeglichen.'),
    ('Begrenzung der Negativliste', 'Innerhalb 3915–3926 ist die Untergliederung vollständig. Außerhalb davon enthält die Datei nur weitere gesetzlich ausgewählte Codes und einen ergänzenden Vergleichsbestand. Keine vollständige Liste sämtlicher weltweit nicht erfasster Waren.'),
    ('Ergänzung ist keine Änderung der Auswahl', 'Nicht gesetzlich genannte Codes bleiben auch nach Ergänzung als „Code nicht ausgewählt“ markiert. Die Auswahl erfolgt nicht aufgrund eines vermeintlich frei wählbaren Alternativcodes.'),
    ('GP-Fokus', 'Alle 130 neunstelligen GP2026-Nummern unter 2221,2222,2223 und 2226 enthalten. Die Klassifikationsfassung älterer Meldungen ist nicht automatisch identisch.'),
    ('Fehlende numerische Zuordnung', '16 technische Teilepositionen unter GP 2226 haben in der Konkordanz keine numerische achtstellige WA-Zuordnung. Neutrale Kennzeichnung: „Keine numerische WA-Zuordnung“. Daraus wird kein Prüfauftrag und kein automatischer steuerlicher Ausschluss abgeleitet.'),
    ('Zwischenüberschriften', 'WA-Ansicht nach vierstelligen WA-Positionen; GP-Ansicht nach vierstelligen GP-Güterklassen. Überschriften entsprechen dem amtlichen übergeordneten Wortlaut. Filter und Sortierung gelten jeweils innerhalb eines Abschnitts.'),
    ('Destatis-Wortlaut', '"https://www.destatis.de/DE/Methoden/Klassifikationen/Gueter-Wirtschaftsklassifikationen/klassifikation-gp-26.html" "https://www.destatis.de/DE/Methoden/Klassifikationen/Aussenhandel/warenverzeichnis-suchmaschine.html"\n"https://destatis.3ce.com/"'),
    ('Konkordanz', 'https://www.destatis.de/DE/Themen/Wirtschaft/Aussenhandel/Methoden/gegenueberstellung-warenverzeichnis-gueterverzeichnis-produktionsstatistiken.html'),
    ('„andere“', 'Restkategorie innerhalb der übergeordneten Warenbeschreibung, abgegrenzt gegenüber zuvor gesondert beschriebenen Unterpositionen. Vollständige Originalseitentexte sind im ausgeblendeten Nachweisblatt enthalten.'),
    ('Zusatzmerkmale', 'Nr.2: höchstens2 mm Dicke. Nr.4: mindestens50 g Kunststoff je kg Ware. Beide Merkmale stehen separat vom amtlichen WA-Wortlaut.'),
    ('Meldungen und Mengen', 'Die verschiedenen Meldesystematiken können unterschiedliche Zuschnitte haben. Mehrfachverknüpfungen sind keine mehrfach addierbaren Mengen und begründen keine Gleichverteilung. Fehlendes Gewicht ist keine Nullmenge.'),
    ('Keine Handlungsempfehlung', 'Die Suchansichten beschreiben die Zuordnung, ihre Grenzen und die gesetzliche Codeauswahl. Sie formulieren keinen Prüfauftrag an Unternehmen und stellen keine verbindliche Artikelklassifikation oder Steuerfestsetzung dar.'),
]
